{
  "schemaVersion": "skill-ir-source-contract-candidate/v1",
  "skillId": "law-to-markdown",
  "name": "Law To Markdown",
  "intent": "将法条/规范文件（.txt/.docx/.pdf）转为 Markdown。适用于用户要求“法条转 markdown”“pdf/docx 转 markdown”。处理 .pdf/.docx 时先检查是否已安装 mineru-ocr skill；未安装先引导安装，安装后优先用 mineru-ocr；仅在用户明确同意时再用本地回退方案。",
  "source": {
    "path": "benchmarks/skill-ir/pilots/law-to-markdown/source/SKILL.md",
    "sha256": "1baed0abb5a4695924761924127e26ff155d1c1ad2e32665f8a557c8768607f0"
  },
  "activationConditions": [],
  "inputs": [
    {
      "id": "task-context",
      "description": "User-provided task context and workspace referenced by the public skill source.",
      "required": true
    }
  ],
  "outputs": [
    {
      "id": "output-01",
      "sourceText": "默认输出到输入文件同目录的 `markdown/` 子目录，并按输入文件名创建独立目录：",
      "required": true
    },
    {
      "id": "output-02",
      "sourceText": "`markdown/<文件名>/`",
      "required": true
    },
    {
      "id": "output-03",
      "sourceText": "默认（`--artifact-level minimal`）输出：",
      "required": true
    },
    {
      "id": "output-04",
      "sourceText": "`<原文件名>+审核报告.md`（详细过程和结论）",
      "required": true
    },
    {
      "id": "output-05",
      "sourceText": "`<原文件名>+最终成果.md`（仅法律文本且审核通过时生成）",
      "required": true
    },
    {
      "id": "output-06",
      "sourceText": "非法律文档（如 GB/标准类）：",
      "required": true
    },
    {
      "id": "output-07",
      "sourceText": "结论为“拒绝处理”",
      "required": true
    },
    {
      "id": "output-08",
      "sourceText": "仅输出 `<原文件名>+审核报告.md`",
      "required": true
    },
    {
      "id": "output-09",
      "sourceText": "不输出 `<原文件名>+最终成果.md`",
      "required": true
    },
    {
      "id": "output-10",
      "sourceText": "审核未通过时会自动保留过程文件用于排查：",
      "required": true
    },
    {
      "id": "output-11",
      "sourceText": "`<文件名>.stage1.md`",
      "required": true
    },
    {
      "id": "output-12",
      "sourceText": "`<文件名>.stage2.md`",
      "required": true
    },
    {
      "id": "output-13",
      "sourceText": "`<文件名>.stage3-check.md`",
      "required": true
    },
    {
      "id": "output-14",
      "sourceText": "若需更多产物可切换：",
      "required": true
    },
    {
      "id": "output-15",
      "sourceText": "`--artifact-level standard`：保留 `stage1/stage2/stage3-check`",
      "required": true
    },
    {
      "id": "output-16",
      "sourceText": "`--artifact-level debug`：保留全部调试产物",
      "required": true
    }
  ],
  "constraints": [
    "输入为 `.txt`：直接转存为 `.md`。",
    "输入为 `.pdf` / `.docx`：",
    "先检查是否已安装 `mineru-ocr` skill。",
    "未安装：提示先安装 `mineru-ocr`，安装地址：",
    "已安装：优先调用 `mineru-ocr` 处理。",
    "调用失败：先提示检查 `mineru-ocr` 配置/Token。",
    "仅当用户明确同意时，才使用本地回退（`python-docx` / `pdfplumber`）。",
    "第一阶段完成后默认执行第二阶段格式调整（仅格式，不改原文字符）：",
    "由调用该 skill 的大模型先判断“法律/非法律”，并把结果传给脚本。",
    "若调用方未传结果，则脚本使用硬规则自动识别（`--law-decision auto`）。",
    "法律名称 `#`",
    "编/分编 `##`",
    "章 `###`",
    "节 `####`",
    "条 `#####`（仅“第X条”为标题；`第X条【条标】`整行为标题不拆）",
    "款/项/目无标题",
    "项、目按标记换行",
    "清理多余空格：去行尾空格、去行首 ASCII 空格、去正文行首全角缩进、规范标题后的空格",
    "若识别为明显非法律文本（如 GB/标准类文档），第二阶段明确拒绝：`Stage2: rejected (non-law-document)`。",
    "若第二阶段未识别法律结构或保真校验失败，则自动 no-op，不改文本。",
    "默认执行第三阶段检查（双子阶段，硬门槛）：",
    "Stage3-A：校验 `stage2` 相对 `stage1` 的文字内容准确性（去标题符号与空白后字符流必须一致）",
    "Stage3-B：校验结构效果（结构层级、条标题规则、非法律策略、空格规范、项/目换行）",
    "任一失败触发自动重走，最多 2 次；仍失败默认报错退出",
    "默认输出到输入文件同目录的 `markdown/` 子目录，并按输入文件名创建独立目录：",
    "`markdown/<文件名>/`",
    "默认（`--artifact-level minimal`）输出：",
    "`<原文件名>+审核报告.md`（详细过程和结论）",
    "`<原文件名>+最终成果.md`（仅法律文本且审核通过时生成）",
    "非法律文档（如 GB/标准类）：",
    "结论为“拒绝处理”",
    "仅输出 `<原文件名>+审核报告.md`"
  ],
  "unresolvedSemantics": [
    "Benchmark task input and output ABI are not derivable from the public skill source alone.",
    "Domain checker and runtime compiler behavior require independent qualification."
  ]
}

